def MemUncountableSchauderSum (b : NormalizedSchauderFamily 𝕜 Γ X) {Y : Type*}
    [NormedAddCommGroup Y] (y : Γ → Y) : Prop :=
  ∃ x : X, ∀ n, b.coord n x = (‖y n‖ : 𝕜)

